from ute_common_abstract_core.aliases_registry import aliases_registry


def access_get_info(ue_alias, info_type, timeout=None):
    ue = aliases_registry()[ue_alias]
    result = ue.get_info(info_type, timeout)
    print("Ue %s has info %s = %s" % (ue_alias, info_type, result))
    return result


def ensure_mcc_mnc_unknown(ue_alias):
    mcc = access_get_info(ue_alias, 'MCC')
    mnc = access_get_info(ue_alias, 'MNC')
    none_value = 'Not attached'
    if mcc != none_value:
        raise Exception("Expected mcc '%s', but mcc = '%s'" % (none_value, mcc))
    if mnc != none_value:
        raise Exception("Expected mnc '%s', but mcc = '%s'" % (none_value, mnc))
